# Pester tests for the device scripts generated by the Check browser extension standard and baseline executor.
# Settings are written into PowerShell that runs on the device, so every value has to stay inside its string literal.

BeforeAll {
    $RepoRoot = Split-Path -Parent (Split-Path -Parent (Split-Path -Parent $PSCommandPath))

    function Test-CIPPStandardLicense { param($StandardName, $TenantFilter, $Preset) $true }
    function Get-CippTable { param($tablename) @{} }
    function Get-CIPPAzDataTableEntity { param($Filter) [pscustomobject]@{ Value = 'cipp.contoso.com' } }
    function New-GraphGetRequest { param($Uri, $tenantid) }
    function New-GraphPostRequest { param($Uri, $Type, $tenantid) }
    function New-GraphBulkRequest { param($tenantid, $Requests) }
    function Write-LogMessage { param($API, $tenant, $message, $sev, $LogData) }
    function Set-CIPPStandardsCompareField { param($FieldName, $FieldValue, $Tenant) }
    function Write-StandardsAlert { param($message, $object, $tenant, $standardName, $standardId) }
    function Set-CIPPAssignedApplication { }
    function Get-NormalizedError { param($Message) $Message }
    function Add-CIPPW32ScriptApplication { param($TenantFilter, $Properties) $script:Captured = $Properties; [pscustomobject]@{ Id = 'app' } }

    . (Join-Path $RepoRoot 'Modules/CIPPCore/Public/Tools/ConvertTo-CIPPScriptBlockValue.ps1')
    . (Join-Path $RepoRoot 'Modules/CIPPStandards/Public/Standards/Invoke-CIPPStandardDeployCheckChromeExtension.ps1')
    . (Join-Path $RepoRoot 'Modules/CIPPBaselines/Public/Executors/Invoke-CIPPBaselineDeployCheckChromeExtension.ps1')

    function New-Settings {
        param([string]$Value)
        @{
            remediate = $true; AssignTo = 'On'
            customRulesUrl = $Value; webhookUrl = $Value; companyName = $Value; productName = $Value; supportEmail = $Value
            supportUrl = $Value; privacyPolicyUrl = $Value; aboutUrl = $Value; primaryColor = $Value; logoUrl = $Value
            enableGenericWebhook = $true
            webhookEvents = @(@{ value = $Value }); urlAllowlist = @(@{ value = $Value })
        }
    }

    # Parse a generated script: no syntax errors, and the marker command never appears as code.
    function Assert-ScriptIsInert {
        param([string]$Script)
        $Tokens = $null; $Errors = $null
        $Ast = [System.Management.Automation.Language.Parser]::ParseInput($Script, [ref]$Tokens, [ref]$Errors)
        $Errors | Should -BeNullOrEmpty
        $Ast.FindAll({ param($Node) $Node -is [System.Management.Automation.Language.CommandAst] -and $Node.GetCommandName() -eq 'Set-Content' }, $true) | Should -BeNullOrEmpty
    }
}

Describe 'Check browser extension device scripts keep settings as data' {
    BeforeDiscovery {
        $Hostile = @(
            @{ Name = 'single quote'; Value = "x'; Set-Content -Path C:\pwn -Value y; '" }
            @{ Name = 'left typographic quote'; Value = "x$([char]0x2018); Set-Content -Path C:\pwn -Value y; $([char]0x2018)" }
            @{ Name = 'right typographic quote'; Value = "x$([char]0x2019); Set-Content -Path C:\pwn -Value y; $([char]0x2019)" }
            @{ Name = 'low-9 quote'; Value = "x$([char]0x201A); Set-Content -Path C:\pwn -Value y; $([char]0x201A)" }
            @{ Name = 'reversed-9 quote'; Value = "x$([char]0x201B); Set-Content -Path C:\pwn -Value y; $([char]0x201B)" }
            @{ Name = 'quote then newline'; Value = "x'`nSet-Content -Path C:\pwn -Value y`n'" }
        )
    }

    BeforeEach { $script:Captured = $null }

    It 'standard: a <Name> in every setting stays inside its literal' -ForEach $Hostile {
        Invoke-CIPPStandardDeployCheckChromeExtension -Tenant 'contoso.onmicrosoft.com' -Settings ([pscustomobject](New-Settings -Value $Value)) | Out-Null
        $script:Captured | Should -Not -BeNullOrEmpty
        Assert-ScriptIsInert -Script $script:Captured.installScript
        Assert-ScriptIsInert -Script $script:Captured.detectionScript
    }

    It 'baseline executor: a <Name> in every setting stays inside its literal' -ForEach $Hostile {
        Invoke-CIPPBaselineDeployCheckChromeExtension -Remediate ([pscustomobject](New-Settings -Value $Value)) -TenantFilter 'contoso.onmicrosoft.com' -Current $null | Out-Null
        $script:Captured | Should -Not -BeNullOrEmpty
        Assert-ScriptIsInert -Script $script:Captured.installScript
        Assert-ScriptIsInert -Script $script:Captured.detectionScript
    }

    It 'ordinary values produce the same install script as before' {
        $Settings = New-Settings -Value 'https://rules.contoso.com/check.json'
        $Settings.primaryColor = '#F77F00'; $Settings.companyName = 'Contoso'
        Invoke-CIPPStandardDeployCheckChromeExtension -Tenant 'contoso.onmicrosoft.com' -Settings ([pscustomobject]$Settings) | Out-Null
        $script:Captured.installScript | Should -Match ([regex]::Escape("-Name 'customRulesUrl'       -PropertyType String -Value 'https://rules.contoso.com/check.json'"))
        $script:Captured.installScript | Should -Match ([regex]::Escape("-Name 'primaryColor'  -PropertyType String -Value '#F77F00'"))
        $script:Captured.installScript | Should -Match ([regex]::Escape("-Name 'companyName'   -PropertyType String -Value 'Contoso'"))
    }
}
